package cards

import "fmt"

// Brand identifies a card network.
type Brand string

const (
	Visa       Brand = "visa"
	Mastercard Brand = "mastercard"
	Amex       Brand = "amex"
)

// FeeBasisPoints returns the processing fee for a brand in hundredths of a percent.
func FeeBasisPoints(brand Brand) (int, error) {
	switch brand {
	case Visa:
		return 150, nil
	case Mastercard:
		return 160, nil
	case Amex:
		return 290, nil
	}
	return 0, fmt.Errorf("fee: unknown card brand %q", brand)
}
